module.exports = function(RED) {
    function SwitchNode(config) {
        RED.nodes.createNode(this, config);
        const node = this;

        node.name = config.name;
        node.property = config.property;
        node.rules = config.rules || [];

        node.on('input', function(msg) {
            const value = RED.util.getMessageProperty(msg, node.property);
            const outMsgs = new Array(node.rules.length).fill(null);

            for (let i = 0; i < node.rules.length; i++) {
                const rule = node.rules[i];

                // 确保 rule 是有效的对象，并且有 t 和 v 属性
                if (!rule || typeof rule.t === 'undefined' || typeof rule.v === 'undefined') {
                    continue;  // 如果规则无效，则跳过这条规则
                }

                const target = Number(rule.v); // 转换 rule.v 为数字

                // 检查 rule.v 是否为有效的数字
                if (isNaN(target)) {
                    continue;  // 如果 rule.v 不是有效数字，则跳过这条规则
                }

                let matched = false;

                // 检查规则类型并进行匹配
                switch (rule.t) {
                    case '==': matched = (value == target); break;
                    case '!=': matched = (value != target); break;
                    case '<': matched = (value < target); break;
                    case '<=': matched = (value <= target); break;
                    case '>': matched = (value > target); break;
                    case '>=': matched = (value >= target); break;
                    default: continue; // 如果操作符 t 无效，则跳过该规则
                }

                if (matched) {
                    outMsgs[i] = msg;  // 如果匹配，则将消息传递到该输出端口
                }
            }

            node.send(outMsgs);  // 发送消息数组
        });

    }

    RED.nodes.registerType("Switch", SwitchNode);
};